-- Modify "products" table
ALTER TABLE "products" ADD CONSTRAINT "products_catalog_kind_unique" UNIQUE ("facility_id", "id", "kind");
-- Create "product_offerings" table
CREATE TABLE "product_offerings" ("facility_id" uuid NOT NULL, "product_id" uuid NOT NULL, "kind" text NOT NULL, "capacity" integer NOT NULL, "minimum_duration_minutes" integer NOT NULL, "maximum_duration_minutes" integer NOT NULL, "minimum_nights" integer NOT NULL, "maximum_nights" integer NOT NULL, PRIMARY KEY ("facility_id", "product_id"), CONSTRAINT "product_offerings_product_kind_fk" FOREIGN KEY ("facility_id", "product_id", "kind") REFERENCES "products" ("facility_id", "id", "kind") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "product_offerings_capacity_valid" CHECK (capacity > 0), CONSTRAINT "product_offerings_duration_valid" CHECK ((minimum_duration_minutes > 0) AND (maximum_duration_minutes >= minimum_duration_minutes)), CONSTRAINT "product_offerings_nights_valid" CHECK (((kind = ANY (ARRAY['private_sauna'::text, 'shared_sauna'::text, 'day_tent'::text])) AND (minimum_nights = 0) AND (maximum_nights = 0)) OR ((kind = 'overnight_tent'::text) AND (minimum_nights > 0) AND (maximum_nights >= minimum_nights))));
